// Verifies X-LendLoop-Signature over the RAW request body before trusting anything in it.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body ?? {});
}

function reject(reason) {
  return [{ json: { valid: false, reason } }];
}

if (!secret) return reject('NO_SECRET');
const sig = headers['x-lendloop-signature'];
const ts = headers['x-lendloop-timestamp'];
if (!sig || !ts) return reject('MISSING_HEADERS');
if (!/^\d{1,12}$/.test(ts)) return reject('MALFORMED_TIMESTAMP');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('STALE_TIMESTAMP');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(String(sig));
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('BAD_SIGNATURE');

let payload;
try { payload = JSON.parse(raw); } catch { return reject('BAD_JSON'); }
const ok = payload && typeof payload.loanId === 'string' && typeof payload.idempotencyKey === 'string'
  && payload.recipient && typeof payload.recipient.email === 'string';
if (!ok) return reject('BAD_PAYLOAD');

return [{ json: { valid: true, payload } }];

// One plain-text message per status. Only fields from the minimal payload are used.
const p = $json.payload;
const app = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const dates = p.startDate === p.endDate ? p.startDate : p.startDate + ' to ' + p.endDate;
const hi = 'Hi ' + p.recipient.name + ',\n\n';
const bye = '\n\nLendLoop - Borrow what you need. Lend what you don\'t.';
const t = {
  pending:   ['New request for your ' + p.toolName, 'A neighbour would like to borrow your ' + p.toolName + ' for ' + dates + '.\nApprove or decline it here: ' + app + '/incoming'],
  approved:  ['Approved: ' + p.toolName, 'Good news! Your request to borrow the ' + p.toolName + ' for ' + dates + ' was approved.\nDetails: ' + app + '/requests'],
  declined:  ['Request declined: ' + p.toolName, 'Your request to borrow the ' + p.toolName + ' for ' + dates + ' was declined. Other tools are on the board: ' + app + '/tools'],
  cancelled: ['Request cancelled: ' + p.toolName, 'The request to borrow your ' + p.toolName + ' for ' + dates + ' was cancelled by the borrower.'],
  returned:  ['Returned: ' + p.toolName, 'The ' + p.toolName + ' you borrowed has been marked as returned. Thanks for being a good neighbour!'],
}[p.status];
if (!t) throw new Error('Unknown status ' + p.status);
return [{ json: { to: p.recipient.email, subject: t[0], text: hi + t[1] + bye } }];

// HMAC-SHA256 over "<timestamp>.<rawBody>", same scheme as convex/lib/signature.ts.
// The secret comes from the n8n container environment, never from this workflow.
const crypto = require('crypto');
function sign(bodyObject) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment');
  const body = JSON.stringify(bodyObject);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { body, signature, timestamp };
}

const p = $('Verify signature').first().json.payload;
const event = {
  idempotencyKey: p.idempotencyKey,
  loanId: p.loanId,
  type: 'request_notification',
  status: 'sent',
  runId: 'n8n:' + $execution.id,
};
return [{ json: sign(event) }];

